 sid=shot['id'];attempt=2 if sid=='WF03-phone' else 1;p=BASE/sid;take=json.loads((p/f'TAKE-r{attempt}.json').read_text());label,seen,deviation=notes[sid];job=retry if attempt==2 else jobs[shot['index']-1]
