 write(p/f'SELECT-REVIEW-r{attempt}.json',review);reviews.append(review)
 selection={'id':sid,'label':label,'original_frames':shot['original_frames'],'segment':shot['segment'],'source':take['final'],'source_start_frame':0,'frames':shot['target_frames'],'raw_source':take['source_raw'],'raw_source_window_frames':take['source_window_frames'],'speed':1,'attempt':attempt,'job_id':job['job_id'],'prompt':binding(p/('PROMPT-r2.txt' if attempt==2 else 'PROMPT.txt')),'take':binding(p/f'TAKE-r{attempt}.json'),'review':binding(p/f'SELECT-REVIEW-r{attempt}.json'),'illustrative':True,'status':'selected_for_review'}
 selections.append(selection)
 manifest={'schema':'ep009-film-selects/v1','status':'selected_for_review','created_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'required_ids':[x['id'] for x in selections],'selections':selections,'original_master':plan['master'],'original_timeline_coordinates':True,'assembly_mapping':'Assembler applies approved brand-pause and bio removals; these source windows are bound to the original locked timeline.','format':{'width':1280,'height':720,'fps':24,'audio_sample_rate':48000,'audio_channels':2},'frames_total':sum(x['frames'] for x in selections),'duration_seconds':sum(x['frames'] for x in selections)/24,'owner_acceptance':False,'claim':'Six illustrative inserts selected by agent for owner review. No release gate is passed.'}
